@startuml
class Customer {
  +vatNumber : string
  +name : string
  +phoneNumber : string
  +address : string
}

class Package {
  +identifierCode : string
  +weight : float
  +deliveryType : string
}

class DeliveryCenter {
  +name : string
  +address : string
}

class Courier {
  +vatNumber : string
  +name : string
  +phoneNumber : string
}

Customer "1" -- "1" DeliveryCenter : is associated to
Customer "1" -- "*" Package : sends
Customer "1" -- "1" Package : receives
DeliveryCenter "1" -- "*" Package : routes
DeliveryCenter "1" -- "*" Courier : employs
Courier "1" -- "0..1" Package : is assigned to
@enduml

